<?php namespace App\Features\Stock\Services;use App\Features\Stock\Models\Stock;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\IOFactory;
class StockExcelService{public function export(int $userId):string{$book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->fromArray(['name','sku','quantity','unit','price','min_stock','status'],null,'A1');foreach(Stock::where('user_id',$userId)->get() as $i=>$s)$sheet->fromArray([$s->name,$s->sku,$s->quantity,$s->unit,$s->price,$s->min_stock,$s->status],null,'A'.($i+2));$path=tempnam(sys_get_temp_dir(),'stock').'.xlsx';(new Xlsx($book))->save($path);return $path;}public function import(int $userId,string $path):int{$sheet=IOFactory::load($path)->getActiveSheet();$rows=$sheet->toArray();$count=0;foreach(array_slice($rows,1) as $r){if(empty($r[0]))continue;Stock::create(['user_id'=>$userId,'name'=>$r[0],'sku'=>$r[1]??null,'quantity'=>max(0,(int)($r[2]??0)),'unit'=>$r[3]??'pcs','price'=>$r[4]??null,'min_stock'=>max(0,(int)($r[5]??5)),'status'=>\App\Features\Stock\Enums\StockStatus::fromQuantity(max(0,(int)($r[2]??0)),max(0,(int)($r[5]??5)))->value]);$count++;}return $count;}}
